// DEMO DATA - synthetic orders for the last 9 local days (today is partial and ignored by the brief).
// Shape mimics a Shopify order payload. Deterministic seed; dates are relative to the run date.
function makeRng(seed) {
  let s = seed >>> 0;
  return function () {
    s = (s + 0x6d2b79f5) >>> 0;
    let t = s;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}
const rand = makeRng(424242);
const pad = (n, w) => String(n).padStart(w, '0');
const tz = String($('Config').first().json.timezone);

const keyFmt = new Intl.DateTimeFormat('en-CA', { timeZone: tz, year: 'numeric', month: '2-digit', day: '2-digit' });
const hourFmt = new Intl.DateTimeFormat('en-GB', { timeZone: tz, hour: '2-digit', hourCycle: 'h23' });
const localKey = (ms) => keyFmt.format(new Date(ms));
const localHour = (ms) => Number(hourFmt.format(new Date(ms)));
// Find an instant whose local date is `key` and local hour is `hour`.
function instantFor(key, hour, minute) {
  const base = Date.parse(key + 'T' + pad(hour, 2) + ':00:00Z');
  for (let off = -14; off <= 14; off++) {
    const cand = base - off * 3600 * 1000;
    if (localKey(cand) === key && localHour(cand) === hour) return cand + minute * 60 * 1000;
  }
  return base;
}

const products = Array.from({ length: 20 }, (_, i) => ({
  sku: 'SKU-' + (1001 + i),
  title: 'Sample Product ' + pad(i + 1, 2),
  price: 35 + ((i * 37) % 21) * 9,
  weight: 1 / (1 + i * 0.35), // a few products sell much more than the rest
}));
const totalWeight = products.reduce((n, p) => n + p.weight, 0);
function pickProduct() {
  let r = rand() * totalWeight;
  for (const p of products) {
    r -= p.weight;
    if (r <= 0) return p;
  }
  return products[0];
}
const dayFactor = [1.15, 0.9, 0.95, 1.0, 1.05, 1.3, 1.45]; // Sun..Sat
const stores = Array.from({ length: 12 }, (_, i) => 'Store A' + pad(i + 1, 2));

const out = [];
let id = 700000;
const nowMs = Date.now();
for (let d = 1; d <= 9; d++) {
  const key = localKey(nowMs - d * 24 * 3600 * 1000);
  const weekday = new Date(key + 'T00:00:00Z').getUTCDay();
  const count = Math.round(110 * dayFactor[weekday] * (0.9 + rand() * 0.2));
  for (let n = 0; n < count; n++) {
    const isOnline = rand() < 0.32;
    const lines = [];
    const lineCount = 1 + Math.floor(rand() * 3);
    let gross = 0;
    for (let k = 0; k < lineCount; k++) {
      const p = pickProduct();
      const qty = 1 + (rand() < 0.2 ? 1 : 0);
      gross += p.price * qty;
      lines.push({ sku: p.sku, title: p.title, quantity: qty, price: p.price.toFixed(2), total_discount: '0.00' });
    }
    const discount = rand() < 0.25 ? Math.round(gross * (5 + Math.floor(rand() * 20))) / 100 : 0;
    id += 1;
    out.push({
      json: {
        id: id,
        name: '#' + (id - 600000),
        created_at: new Date(instantFor(key, 9 + Math.floor(rand() * 12), Math.floor(rand() * 60))).toISOString(),
        source_name: isOnline ? 'web' : 'pos',
        cancelled_at: rand() < 0.03 ? new Date(nowMs).toISOString() : null,
        test: false,
        currency: 'USD',
        total_discounts: discount.toFixed(2),
        total_price: (gross - discount).toFixed(2),
        note_attributes: isOnline ? [] : [{ name: 'store', value: stores[Math.floor(rand() * 12)] }],
        line_items: lines,
      },
    });
  }
}
return out;

// All numbers in the brief are computed here, deterministically. The LLM never calculates anything.
//
// Definitions
//   order counted : not cancelled (cancelled_at empty) and not a test order
//   revenue       : sum of total_price of counted orders (what the customer paid, shipping and tax as in the order total)
//   AOV           : revenue / orders
//   day           : calendar date in Config.timezone; "yesterday" = today - 1 day
//   comparisons   : yesterday vs the day before, and yesterday vs the same weekday one week earlier
//   channel       : source_name "pos" = Retail (POS), anything else = Online
//   product value : line price * quantity - line total_discount
const cfg = $('Config').first().json;
const tz = String(cfg.timezone);
const currency = String(cfg.currency);
const topN = Number(cfg.topN);

const round2 = (n) => Math.round(n * 100) / 100;
const round1 = (n) => Math.round(n * 10) / 10;
const text = (v) => (v === undefined || v === null ? '' : String(v).trim());

const keyFmt = new Intl.DateTimeFormat('en-CA', { timeZone: tz, year: 'numeric', month: '2-digit', day: '2-digit' });
const localKey = (ms) => keyFmt.format(new Date(ms));
const shift = (key, days) => {
  const d = new Date(key + 'T00:00:00Z');
  d.setUTCDate(d.getUTCDate() + days);
  return d.toISOString().slice(0, 10);
};
const WEEKDAYS = ['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday'];
const weekdayOf = (key) => WEEKDAYS[new Date(key + 'T00:00:00Z').getUTCDay()];

const today = localKey(Date.now());
const day = shift(today, -1);
const dayBefore = shift(day, -1);
const lastWeek = shift(day, -7);

function storeOf(o) {
  if (text(o.source_name).toLowerCase() !== 'pos') return 'Online';
  const attrs = Array.isArray(o.note_attributes) ? o.note_attributes : [];
  const attr = attrs.find((a) => a && String(a.name).toLowerCase() === 'store');
  if (attr && text(attr.value)) return text(attr.value);
  if (text(o.store_name)) return text(o.store_name);
  if (o.location_id) return 'Location ' + o.location_id;
  return 'Retail (unassigned)';
}

const valid = $input.all().map((i) => i.json).filter(
  (o) => o && o.created_at && !o.cancelled_at && o.test !== true && Number.isFinite(Number(o.total_price))
);
const byDay = {};
for (const o of valid) {
  const k = localKey(Date.parse(o.created_at));
  (byDay[k] || (byDay[k] = [])).push(o);
}
function metrics(key) {
  const list = byDay[key] || [];
  const revenue = list.reduce((n, o) => n + Number(o.total_price), 0);
  const units = list.reduce((n, o) => n + (o.line_items || []).reduce((m, l) => m + Number(l.quantity || 0), 0), 0);
  return { orders: list.length, revenue: round2(revenue), aov: list.length ? round2(revenue / list.length) : null, units: units };
}
function delta(cur, base) {
  if (base === null || base === undefined || cur === null || cur === undefined) return { abs: null, pct: null, direction: 'n/a' };
  const abs = round2(cur - base);
  const pct = base === 0 ? null : round1(((cur - base) / base) * 100);
  return { abs: abs, pct: pct, direction: abs > 0 ? 'up' : abs < 0 ? 'down' : 'flat' };
}
function compare(key) {
  const m = metrics(key);
  const y = metrics(day);
  const has = m.orders > 0;
  return {
    date: key,
    weekday: weekdayOf(key),
    orders: m.orders,
    revenue: m.revenue,
    aov: m.aov,
    revenue_change: has ? delta(y.revenue, m.revenue) : delta(null, null),
    orders_change: has ? delta(y.orders, m.orders) : delta(null, null),
    aov_change: has ? delta(y.aov, m.aov) : delta(null, null),
  };
}

const y = metrics(day);
const list = byDay[day] || [];

// products
const prod = {};
for (const o of list) {
  for (const l of o.line_items || []) {
    const key = text(l.sku) || text(l.title);
    const p = prod[key] || (prod[key] = { sku: text(l.sku) || null, title: text(l.title), units: 0, revenue: 0 });
    const qty = Number(l.quantity || 0);
    p.units += qty;
    p.revenue += Number(l.price || 0) * qty - Number(l.total_discount || 0);
  }
}
const productTotal = Object.values(prod).reduce((n, p) => n + p.revenue, 0);
const topProducts = Object.values(prod)
  .sort((a, b) => b.revenue - a.revenue || a.title.localeCompare(b.title))
  .slice(0, topN)
  .map((p, i) => ({
    rank: i + 1, sku: p.sku, title: p.title, units: p.units, revenue: round2(p.revenue),
    share_of_product_revenue_pct: productTotal ? round1((p.revenue / productTotal) * 100) : null,
  }));

// split helpers
function split(keyFn) {
  const g = {};
  for (const o of list) {
    const k = keyFn(o);
    const e = g[k] || (g[k] = { name: k, orders: 0, revenue: 0 });
    e.orders += 1;
    e.revenue += Number(o.total_price);
  }
  return Object.values(g)
    .sort((a, b) => b.revenue - a.revenue || a.name.localeCompare(b.name))
    .map((e) => ({ name: e.name, orders: e.orders, revenue: round2(e.revenue), share_pct: y.revenue ? round1((e.revenue / y.revenue) * 100) : null }));
}
const byChannel = split((o) => (text(o.source_name).toLowerCase() === 'pos' ? 'Retail (POS)' : 'Online'));
const allStores = split(storeOf);
const topStores = allStores.slice(0, topN);

const warnings = [];
if (y.orders === 0) warnings.push('No orders found for ' + day + '. Check the data source and the timezone setting.');
if (!(byDay[dayBefore] || []).length) warnings.push('No orders found for the day before (' + dayBefore + '), so day-over-day change is n/a.');
if (!(byDay[lastWeek] || []).length) warnings.push('No orders found for the same weekday last week (' + lastWeek + '), so that comparison is n/a.');

const facts = {
  brand: String(cfg.brandName),
  currency: currency,
  report_date: day,
  weekday: weekdayOf(day),
  revenue: y.revenue,
  orders: y.orders,
  aov: y.aov,
  units: y.units,
  vs_day_before: compare(dayBefore),
  vs_same_weekday_last_week: compare(lastWeek),
  top_products: topProducts,
  by_channel: byChannel,
  top_stores: topStores,
  stores_not_shown: Math.max(0, allStores.length - topStores.length),
  warnings: warnings,
};
return [{ json: { facts: facts } }];

// Builds the fallback brief from the facts first, then the (optional) LLM request.
const cfg = $('Config').first().json;
const f = $input.first().json.facts;
const cur = f.currency;

const money = (n) => (n === null || n === undefined ? 'n/a' : cur + ' ' + n.toFixed(2).replace(/\B(?=(\d{3})+(?!\d))/g, ','));
const pct = (n) => (n === null || n === undefined ? 'n/a' : (n > 0 ? '+' : '') + n + '%');
const cmp = (c) =>
  c.orders === 0
    ? 'n/a (no orders on ' + c.date + ')'
    : 'revenue ' + pct(c.revenue_change.pct) + ', orders ' + pct(c.orders_change.pct) + ', AOV ' + pct(c.aov_change.pct);

const lines = [];
lines.push('Daily sales brief - ' + f.brand + ' - ' + f.weekday + ' ' + f.report_date);
lines.push('Revenue ' + money(f.revenue) + ' from ' + f.orders + ' orders (AOV ' + money(f.aov) + ', ' + f.units + ' units).');
lines.push('Vs day before (' + f.vs_day_before.weekday + ' ' + f.vs_day_before.date + '): ' + cmp(f.vs_day_before) + '.');
lines.push('Vs same weekday last week (' + f.vs_same_weekday_last_week.date + '): ' + cmp(f.vs_same_weekday_last_week) + '.');
if (f.top_products.length) {
  lines.push('Top products: ' + f.top_products.map((p) => p.rank + '. ' + (p.sku || p.title) + ' ' + money(p.revenue) + ' (' + p.units + ' units)').join('; ') + '.');
}
if (f.by_channel.length) {
  lines.push('Channels: ' + f.by_channel.map((c) => c.name + ' ' + c.share_pct + '% (' + c.orders + ' orders)').join(', ') + '.');
}
if (f.top_stores.length) {
  lines.push('Top places: ' + f.top_stores.map((s) => s.name + ' ' + money(s.revenue)).join('; ') + '.');
}
for (const w of f.warnings) lines.push('Note: ' + w);
const templateBrief = lines.join('\n');

const system =
  'You write the daily sales brief for a retail manager.\n' +
  'Rules:\n' +
  '1. Use only the numbers and names present in FACTS_JSON. Never calculate, estimate, round differently, abbreviate (no k or M) or invent a number, product, store or cause.\n' +
  '2. Write numbers exactly as they appear in FACTS_JSON. Put the currency code before money amounts.\n' +
  '3. If a value is null or n/a, write n/a. If warnings is not empty, mention each warning in one line.\n' +
  '4. State what changed and by how much. Do not explain causes and do not give advice.\n' +
  '5. Plain text, 5 to 8 short lines, no markdown, no emoji, at most 120 words.';

return [
  {
    json: {
      facts: f,
      template_brief: templateBrief,
      llm_request: {
        model: String(cfg.llmModel),
        max_tokens: 500,
        system: system,
        messages: [{ role: 'user', content: 'FACTS_JSON:\n' + JSON.stringify(f) }],
      },
    },
  },
];

// Use the LLM brief only if it passes the checks, otherwise the template brief.
// Input is either the Anthropic response (LLM path) or the Build Prompt item (no-LLM path).
const base = $('Build Prompt').first().json;
const input = $input.first().json;
const llmText = input && Array.isArray(input.content) && input.content[0] ? String(input.content[0].text || '') : '';

function numbersIn(s) {
  return (String(s).match(/\d[\d,]*\.?\d*/g) || [])
    .map((t) => ({ val: Number(t.replace(/,/g, '').replace(/\.$/, '')), dec: ((t.split('.')[1] || '').match(/\d/g) || []).length }))
    .filter((x) => !Number.isNaN(x.val));
}
// Every number in the LLM text must match a number in the facts (compared by absolute value, within its own rounding).
function unknownNumbers(text, facts) {
  const known = numbersIn(JSON.stringify(facts)).map((x) => Math.abs(x.val));
  return numbersIn(text).filter((n) => !known.some((k) => Math.abs(k - n.val) <= 0.5 * Math.pow(10, -n.dec) + 1e-9));
}

let brief = base.template_brief;
let source = 'template';
let note = llmText ? '' : 'LLM not used or returned no text';
if (llmText) {
  const lines = llmText.split('\n').map((l) => l.trim()).filter(Boolean);
  const unknown = unknownNumbers(llmText, base.facts);
  if (lines.length < 3 || lines.length > 12) note = 'LLM output rejected: expected 3-12 lines, got ' + lines.length;
  else if (unknown.length) note = 'LLM output rejected: numbers not found in facts: ' + unknown.map((n) => n.val).join(', ');
  else {
    brief = lines.join('\n');
    source = 'llm';
    note = '';
  }
}
return [{ json: { brief: brief, summary_source: source, summary_note: note, facts: base.facts } }];

// Demo result: nothing is sent. Shows the brief and the computed facts it was written from.
const r = $input.first().json;
return [
  {
    json: {
      mode: 'demo',
      note: 'Demo run: nothing was sent to Telegram or Slack.',
      brief: r.brief,
      summary_source: r.summary_source,
      summary_note: r.summary_note,
      facts: r.facts,
    },
  },
];
